// ctx.responses is an array — one entry per outgoing connector whose target sent a
// response last tick. Empty most ticks; has an entry the one tick after Responder sets one.
if (ctx.responses.length > 0) {
  ctx.log('received response "' + ctx.responses[0].value + '" from ' + ctx.responses[0].fromLabel);
}
return { value: 'request-' + ctx.tick, state: {} };

// ctx.inputs[0].value is undefined until Requester's first tick has committed.
if (ctx.inputs.length === 0 || ctx.inputs[0].value === undefined) return { value: null, state: {} };
const received = ctx.inputs[0].value;

// Only send a response the FIRST time we see this particular value — the `response`
// field is a single slot (not a queue), and the engine already guarantees it's never
// auto-resent, but tracking lastAcked here is still good practice: it stops THIS
// script's own logic from re-triggering on a value it's already handled.
if (ctx.state.lastAcked === received) {
  return { value: received, state: ctx.state };
}
return { value: received, state: { lastAcked: received }, response: 'ack:' + received };
